import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import fs from "fs/promises";

const STATE_FILE = "/home/user/pool/pool-state.json";

export interface WorkspaceEntry {
  name: string;
  bucket: string;
  credentials: {
    accessKeyId: string;
    secretAccessKey: string;
  };
}

export interface PoolState {
  workspaces: WorkspaceEntry[];
}

export async function provisionPool(n: number) {
  const promises = [];
  for (let i = 1; i <= n; i++) {
    const name = `pool-${n}-${i}`;
    promises.push(
      createWorkspace(name, {
        ttl: { days: 1 },
        credentials: { role: "Editor" },
      })
    );
  }

  const results = await Promise.all(promises);

  const workspaces: WorkspaceEntry[] = [];
  for (let i = 0; i < results.length; i++) {
    const res = results[i];
    if (res.error) {
      throw res.error;
    }
    if (!res.data) {
      throw new Error("No data returned from createWorkspace");
    }
    workspaces.push({
      name: `pool-${n}-${i + 1}`,
      bucket: res.data.bucket,
      credentials: {
        accessKeyId: res.data.credentials!.accessKeyId,
        secretAccessKey: res.data.credentials!.secretAccessKey,
      },
    });
  }

  const state: PoolState = { workspaces };
  await fs.writeFile(STATE_FILE, JSON.stringify(state, null, 2));
}

export async function assignTask(agentIndex: number, text: string) {
  let stateData: string;
  try {
    stateData = await fs.readFile(STATE_FILE, "utf-8");
  } catch (e) {
    throw new Error("pool-state.json is missing");
  }

  const state: PoolState = JSON.parse(stateData);

  if (agentIndex < 1 || agentIndex > state.workspaces.length) {
    throw new Error(`Agent index ${agentIndex} out of range`);
  }

  const workspace = state.workspaces[agentIndex - 1];

  const s3 = new S3Client({
    endpoint: "https://t3.storage.dev",
    region: "auto",
    credentials: {
      accessKeyId: workspace.credentials.accessKeyId,
      secretAccessKey: workspace.credentials.secretAccessKey,
    },
  });

  await s3.send(
    new PutObjectCommand({
      Bucket: workspace.bucket,
      Key: "task.txt",
      Body: text,
    })
  );
}

export async function status() {
  const stateData = await fs.readFile(STATE_FILE, "utf-8");
  const state: PoolState = JSON.parse(stateData);
  console.log(`pool size: ${state.workspaces.length}`);
  for (const ws of state.workspaces) {
    console.log(ws.bucket);
  }
}

export async function teardownPool() {
  const stateData = await fs.readFile(STATE_FILE, "utf-8");
  const state: PoolState = JSON.parse(stateData);

  const results = await Promise.allSettled(
    state.workspaces.map((ws) =>
      teardownWorkspace({
        bucket: ws.bucket,
        credentials: ws.credentials,
      })
    )
  );

  await fs.unlink(STATE_FILE);

  const failures = results.filter(
    (r) =>
      r.status === "rejected" || (r.status === "fulfilled" && r.value.error)
  );
  if (failures.length > 0) {
    throw new Error("Some teardowns failed");
  }
}

import { provisionPool, assignTask, status, teardownPool } from "./manager.ts";

async function main() {
  const args = process.argv.slice(2);
  const subcommand = args[0];

  try {
    switch (subcommand) {
      case "provision": {
        const n = parseInt(args[1], 10);
        if (isNaN(n)) {
          console.error("Usage: provision <N>");
          process.exit(1);
        }
        await provisionPool(n);
        break;
      }
      case "assign-task": {
        const index = parseInt(args[1], 10);
        const text = args[2];
        if (isNaN(index) || text === undefined) {
          console.error("Usage: assign-task <agent-index> <text>");
          process.exit(1);
        }
        await assignTask(index, text);
        break;
      }
      case "status": {
        await status();
        break;
      }
      case "teardown": {
        await teardownPool();
        break;
      }
      default:
        console.error("Unknown subcommand. Usage: cli.ts <provision|assign-task|status|teardown>");
        process.exit(1);
    }
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}

main();
